$(document).ready(function () {

    // Menu
    function initDropdowns() {
        $('.has-dropdown').off('mouseenter mouseleave click');

        if (window.innerWidth > 992) {
            $('.has-dropdown').hover(function () {
                $(this).toggleClass('has-dropdown--active');
            });
        } else {
            $('.has-dropdown').on('click', function () {
                $(this).toggleClass('has-dropdown--active');
            });
        }
    }

    initDropdowns();

    $(window).resize(function () {
        initDropdowns();
    });

    $('.burger').click(function () {
        $(this).toggleClass('burger--active')
        $('.header__list').toggleClass('header__list--active')
        $('body').toggleClass('fixed-body')
    })

    // Tabs
    $(".tab").hover(function () {
        let path = $(this).attr("data-tab-path")
        $(this).siblings(".tab").removeClass("tab--active")
        $(this).addClass("tab--active")

        $(this).parents(".tabs-inner").find(".tab__content").removeClass("tab__content--active")
        $(this).parents(".tabs-inner").find(`.tab__content[data-content-path="${path}"]`).addClass("tab__content--active")
    })

    // Custom-select
    $('.custom-select').each(function () {
        let $select = $(this);

        $select.find('.select-selected').on('click', function (e) {
            e.stopPropagation();

            $('.custom-select').not($select).removeClass('open');

            $select.toggleClass('open');
        });

        $select.find('.select-item').on('click', function () {
            let $item = $(this);
            let $clone = $item.clone();

            $select.find('.select-item').removeClass('is-active');
            $item.addClass('is-active');

            $select.find('.select-selected').html($clone);

            $select.removeClass('open');

            $select.trigger('change', [$item.data()]);
        });
    });

    $(document).on('click', function () {
        $('.custom-select').removeClass('open');
    });

})

// Animation
gsap.registerPlugin(ScrollTrigger);

// Main
gsap.utils.toArray(".main__inner").forEach((section) => {

    gsap.from(section, {
        y: 80,
        opacity: 0,
        duration: 1.5,
        ease: "power3.out",
        scrollTrigger: {
            trigger: section,
            start: "top 75%",
            once: true
        }
    });

});

// SectionTop
